-- ============================================================
-- OPTIMIZE V4.1 — MASSIVE COLLECTION UPDATE
-- 200 cartes + 100 compagnons + codes Supabase + colonnes boutique/gacha
-- Ne supprime pas tes données utilisateur.
-- ============================================================

alter table public.companions add column if not exists price integer not null default 0;
alter table public.companions add column if not exists gacha_only boolean not null default false;
alter table public.companions add column if not exists starter boolean not null default false;
alter table public.companions add column if not exists value text;
alter table public.companions add column if not exists boost_scope text not null default 'equipped';

create table if not exists public.secret_codes (
  code text primary key,
  label text,
  message text,
  reward_type text not null default 'tickets',
  reward_id text,
  tickets integer not null default 0,
  min_level integer not null default 1,
  active boolean not null default true,
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz
);

create table if not exists public.user_secret_codes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  code text not null,
  reward_type text,
  reward_id text,
  used_at timestamptz not null default now(),
  unique(user_id, code)
);

on conflict (id) do update set
  name = excluded.name,
  rarity = excluded.rarity,
  category = excluded.category,
  description = excluded.description,
  condition_hint = excluded.condition_hint,
  boost_type = excluded.boost_type,
  boost_value = excluded.boost_value,
  season = excluded.season,
  icon = excluded.icon,
  active = excluded.active,
  unlocks = excluded.unlocks,
  updated_at = now();

on conflict (id) do update set
  name = excluded.name,
  rarity = excluded.rarity,
  family = excluded.family,
  description = excluded.description,
  phrase = excluded.phrase,
  boost_type = excluded.boost_type,
  boost_value = excluded.boost_value,
  season = excluded.season,
  icon = excluded.icon,
  active = excluded.active,
  unlocks = excluded.unlocks,
  price = excluded.price,
  gacha_only = excluded.gacha_only,
  value = excluded.value,
  boost_scope = excluded.boost_scope,
  starter = excluded.starter,
  updated_at = now();

on conflict (code) do update set
  label = excluded.label,
  message = excluded.message,
  reward_type = excluded.reward_type,
  reward_id = excluded.reward_id,
  tickets = excluded.tickets,
  min_level = excluded.min_level,
  active = excluded.active,
  expires_at = excluded.expires_at,
  updated_at = now();

alter table public.secret_codes enable row level security;
alter table public.user_secret_codes enable row level security;

drop policy if exists secret_codes_select_active on public.secret_codes;
create policy secret_codes_select_active on public.secret_codes
  for select using (active = true);

drop policy if exists user_secret_codes_select_own on public.user_secret_codes;
drop policy if exists user_secret_codes_insert_own on public.user_secret_codes;
drop policy if exists user_secret_codes_update_own on public.user_secret_codes;
drop policy if exists user_secret_codes_delete_own on public.user_secret_codes;

create policy user_secret_codes_select_own on public.user_secret_codes
  for select using (auth.uid() = user_id);

create policy user_secret_codes_insert_own on public.user_secret_codes
  for insert with check (auth.uid() = user_id);

create policy user_secret_codes_update_own on public.user_secret_codes
  for update using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

create policy user_secret_codes_delete_own on public.user_secret_codes
  for delete using (auth.uid() = user_id);
